 58	
 59	  /* 0x11: Sleep Out */
 60	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x11, 0x00);
 61	  HAL_Delay(120);
 62	  /* 0x51: WRDISBV - dat do sang toi da (0xFF) */
 63	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x51, 0xFF);
 64	  /* 0x53: WRCTRLD - bat BCTRL (0x2C: BCTRL=1, DD=1, BL=1) */
 65	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x53, 0x2C);
 66	  /* 0x29: Display On */
 67	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x29, 0x00);
 68	  HAL_Delay(50);
 69	
 70	  /* Doc cac thanh ghi trang thai DCS cua panel va luu ma tra ve */
 71	  g_panel_read_ret[0] = DSI_IO_ReadCmd(0xDA, (uint8_t *)&g_panel_status[0], 1); g_panel_dcs[0] = g_panel_status[0]; /* ID1 */
 72	  g_panel_read_ret[1] = DSI_IO_ReadCmd(0x0A, (uint8_t *)&g_panel_status[1], 1); g_panel_dcs[1] = g_panel_status[1]; /* Power Mode */
 73	  g_panel_read_ret[2] = DSI_IO_ReadCmd(0x0B, (uint8_t *)&g_panel_status[2], 1); g_panel_dcs[2] = g_panel_status[2]; /* MADCTL */
 74	  g_panel_read_ret[3] = DSI_IO_ReadCmd(0x0C, (uint8_t *)&g_panel_status[3], 1); g_panel_dcs[3] = g_panel_status[3]; /* COLMOD */
 75	  g_panel_read_ret[4] = DSI_IO_ReadCmd(0x52, (uint8_t *)&g_panel_status[4], 1); g_panel_dcs[4] = g_panel_status[4]; /* Brightness */
 76	  g_panel_read_ret[5] = DSI_IO_ReadCmd(0x54, (uint8_t *)&g_panel_status[5], 1); g_panel_dcs[5] = g_panel_status[5]; /* CTRL Display */
 77	  g_panel_read_ret[6] = DSI_IO_ReadCmd(0x0F, (uint8_t *)&g_panel_status[6], 1); g_panel_dcs[6] = g_panel_status[6]; /* Self-Diagnostic */
 78	  g_panel_read_ret[7] = DSI_IO_ReadCmd(0x0D, (uint8_t *)&g_panel_status[7], 1); g_panel_dcs[7] = g_panel_status[7]; /* Image Mode */
