 82	
 83	  uint32_t lcd_w = BSP_LCD_GetXSize();
 84	
 85	  /* 7. Ve Logo PTIT (240x240) ra giua man hinh */
 86	  uint32_t logo_x = (lcd_w > LOGO_PTIT_WIDTH) ? ((lcd_w - LOGO_PTIT_WIDTH) / 2) : 0;
 87	  uint32_t logo_y = 30;
 88	  DrawLogo(logo_x, logo_y);
